-- PADEL ARENA MANAGER 8.0 - DATABASE COMPLETO E NON DISTRUTTIVO
-- Incollare tutto in Supabase > SQL Editor > New query > Run.
create extension if not exists pgcrypto;

create table if not exists public.profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 email text, role text not null default 'collaborator', display_name text, created_at timestamptz default now(), updated_at timestamptz default now()
);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin
 insert into public.profiles(id,email,role,display_name) values(new.id,new.email,case when lower(new.email)='padelarenareggioemilia@gmail.com' then 'admin' else 'collaborator' end,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))) on conflict(id) do update set email=excluded.email; return new; end$$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert or update of email on auth.users for each row execute function public.handle_new_user();
insert into public.profiles(id,email,role,display_name) select id,email,case when lower(email)='padelarenareggioemilia@gmail.com' then 'admin' else 'collaborator' end,coalesce(raw_user_meta_data->>'display_name',split_part(email,'@',1)) from auth.users on conflict(id) do update set email=excluded.email,role=case when lower(excluded.email)='padelarenareggioemilia@gmail.com' then 'admin' else public.profiles.role end;

create table if not exists public.players(id text primary key,data jsonb not null default '{}'::jsonb,photo_url text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.tournaments(id text primary key,name text,event_date date,club text,category text,competition_type text,logo_url text,share_token text unique not null default gen_random_uuid()::text,status text not null default 'published',data jsonb not null default '{}'::jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
-- Migrazione sicura di share_token: compatibile sia con vecchie colonne UUID sia con colonne TEXT.
alter table public.tournaments add column if not exists share_token text;
do $$
declare current_type text;
begin
 select data_type into current_type
 from information_schema.columns
 where table_schema='public' and table_name='tournaments' and column_name='share_token';

 if current_type is distinct from 'text' then
  alter table public.tournaments alter column share_token drop default;
  alter table public.tournaments alter column share_token type text using share_token::text;
 end if;
end$$;
alter table public.tournaments alter column share_token set default gen_random_uuid()::text;
update public.tournaments
set share_token=gen_random_uuid()::text
where share_token is null or btrim(share_token)='';
alter table public.tournaments alter column share_token set not null;
do $$declare c record;begin for c in select conname from pg_constraint where conrelid='public.tournaments'::regclass and contype='c' loop execute format('alter table public.tournaments drop constraint %I',c.conname);end loop;end$$;
alter table public.tournaments add constraint tournaments_status_check check(status in('draft','published','active','registration_open','registration_closed','completed','archived','cancelled'));
create unique index if not exists tournaments_share_token_uidx on public.tournaments(share_token);

create table if not exists public.public_registrations(id text primary key default gen_random_uuid()::text,tournament_id text not null references public.tournaments(id) on delete cascade,mode text not null check(mode in('single','pair')),primary_payload jsonb not null,partner_payload jsonb,primary_player_id text references public.players(id),partner_player_id text references public.players(id),status text not null default 'new' check(status in('new','accepted','rejected','waitlist','imported')),created_at timestamptz default now(),updated_at timestamptz default now());

create table if not exists public.championship_teams(
 id text primary key, team_name text not null, series text, club_legal_name text, club_tax_id text, club_address text, club_postal_code text, club_town text, club_province text, club_phone text, club_email text, home_court_address text, home_day text, home_time text, captain_name text, captain_email text, captain_phone text, captain_birth_date date, captain_birth_place text, captain_residence text, invite_token text unique not null, player_invite_token text unique not null, access_enabled boolean default false, roster_open boolean default true, player_self_registration_enabled boolean default true, team_logo_url text, created_at timestamptz default now(), updated_at timestamptz default now()
);
alter table public.championship_teams add column if not exists team_name text;
alter table public.championship_teams add column if not exists series text;
alter table public.championship_teams add column if not exists club_legal_name text;
alter table public.championship_teams add column if not exists club_tax_id text;
alter table public.championship_teams add column if not exists club_address text;
alter table public.championship_teams add column if not exists club_postal_code text;
alter table public.championship_teams add column if not exists club_town text;
alter table public.championship_teams add column if not exists club_province text;
alter table public.championship_teams add column if not exists club_phone text;
alter table public.championship_teams add column if not exists club_email text;
alter table public.championship_teams add column if not exists home_court_address text;
alter table public.championship_teams add column if not exists home_day text;
alter table public.championship_teams add column if not exists home_time text;
alter table public.championship_teams add column if not exists captain_name text;
alter table public.championship_teams add column if not exists captain_email text;
alter table public.championship_teams add column if not exists captain_phone text;
alter table public.championship_teams add column if not exists captain_birth_date date;
alter table public.championship_teams add column if not exists captain_birth_place text;
alter table public.championship_teams add column if not exists captain_residence text;
alter table public.championship_teams add column if not exists invite_token text;
alter table public.championship_teams add column if not exists player_invite_token text;
alter table public.championship_teams add column if not exists access_enabled boolean default false;
alter table public.championship_teams add column if not exists roster_open boolean default true;
alter table public.championship_teams add column if not exists player_self_registration_enabled boolean default true;
alter table public.championship_teams add column if not exists team_logo_url text;
alter table public.championship_teams add column if not exists updated_at timestamptz default now();
create unique index if not exists championship_teams_invite_uidx on public.championship_teams(invite_token);
create unique index if not exists championship_teams_player_invite_uidx on public.championship_teams(player_invite_token);
create table if not exists public.captain_team_access(user_id uuid references auth.users(id) on delete cascade,team_id text references public.championship_teams(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,team_id));
create table if not exists public.championship_roster_players(
 id uuid primary key default gen_random_uuid(), team_id text not null references public.championship_teams(id) on delete cascade, first_name text not null,last_name text not null,birth_date date not null,birth_place text not null,postal_code text not null,residence_town text not null,residence_province text not null,phone text not null,email text not null,gender text,level text,notes text,photo_data text,status text not null default 'pending' check(status in('pending','approved','rejected')),decision_reason text,submitted_by uuid,created_at timestamptz default now(),updated_at timestamptz default now(),unique(team_id,email)
);

