-- funzioni pubbliche tornei
drop function if exists public.public_tournament_for_registration(uuid);
drop function if exists public.public_tournament_for_registration(text);
drop function if exists public.public_search_players_for_registration(uuid,text);
drop function if exists public.public_search_players_for_registration(text,text);
drop function if exists public.public_submit_tournament_registration_request(uuid,text,jsonb,jsonb);
drop function if exists public.public_submit_tournament_registration_request(text,text,jsonb,jsonb);
create or replace function public.public_tournament_for_registration(p_share_token text) returns jsonb language plpgsql security definer set search_path=public as $$declare t public.tournaments; d jsonb; count_ok int;begin select * into t from public.tournaments where share_token=p_share_token limit 1;if not found then return null;end if;d=coalesce(t.data,'{}'::jsonb);select count(*) into count_ok from public.public_registrations where tournament_id=t.id and status in('accepted','imported');return jsonb_build_object('id',t.id,'name',coalesce(t.name,d->>'name'),'date',coalesce(t.event_date::text,d->>'date'),'start_time',d->>'startTime','end_date',d->>'endDate','end_time',d->>'endTime','club',coalesce(t.club,d->>'club'),'address',d->>'customAddress','category',coalesce(t.category,d->>'category'),'competition_type',coalesce(t.competition_type,d->>'competitionType'),'logo_url',coalesce(t.logo_url,d->>'logoUrl'),'description',d->>'description','entry_fee',coalesce((d->>'entryFee')::numeric,0),'max_participants',coalesce((d->>'registrationCapacity')::int,(d->>'maxParticipants')::int),'available_places',greatest(0,coalesce((d->>'registrationCapacity')::int,(d->>'maxParticipants')::int,999)-count_ok),'registration_open',coalesce((d->>'registrationOpen')::boolean,true),'poster_theme',coalesce(d->>'posterTheme','eden_summer'),'accent','#9dff25');end$$;
create or replace function public.public_search_players_for_registration(p_share_token text,p_query text) returns table(id text,full_name text) language sql security definer set search_path=public as $$select p.id,trim(coalesce(p.data->>'firstName','')||' '||coalesce(p.data->>'lastName','')) from public.players p where exists(select 1 from public.tournaments t where t.share_token=p_share_token) and lower(trim(coalesce(p.data->>'firstName','')||' '||coalesce(p.data->>'lastName',''))) like '%'||lower(trim(p_query))||'%' order by 2 limit 20$$;
create or replace function public.public_submit_tournament_registration_request(p_share_token text,p_mode text,p_primary jsonb,p_partner jsonb default null) returns jsonb language plpgsql security definer set search_path=public as $$declare tid text; rid text; cap int; accepted_count int; st text:='new';begin select id,coalesce((data->>'registrationCapacity')::int,(data->>'maxParticipants')::int) into tid,cap from public.tournaments where share_token=p_share_token and coalesce((data->>'registrationOpen')::boolean,true)=true;if tid is null then raise exception 'Iscrizioni chiuse o torneo non trovato';end if;if p_mode not in('single','pair') then raise exception 'Modalità non valida';end if;select count(*) into accepted_count from public.public_registrations where tournament_id=tid and status in('accepted','imported');if cap is not null and accepted_count>=cap then st:='waitlist';end if;insert into public.public_registrations(tournament_id,mode,primary_payload,partner_payload,status) values(tid,p_mode,p_primary,p_partner,st) returning id into rid;return jsonb_build_object('id',rid,'status',st,'message',case when st='waitlist' then 'Posti esauriti: richiesta inserita in lista d’attesa.' else 'Richiesta inviata all’organizzatore.' end);end$$;
create or replace function public.admin_process_public_registration(p_registration_id text,p_action text,p_capacity integer default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.public_registrations; pp jsonb; pid1 text; pid2 text; ids jsonb;
begin
 if not exists(select 1 from public.profiles where id=auth.uid() and role='admin') then raise exception 'Operazione riservata all’amministratore'; end if;
 select * into r from public.public_registrations where id=p_registration_id for update;
 if not found then raise exception 'Richiesta non trovata'; end if;
 if p_action='accepted' then
  pp=r.primary_payload;
  if pp->>'kind'='existing' then pid1=pp->>'player_id'; else pid1='p_'||gen_random_uuid()::text; insert into public.players(id,data) values(pid1,pp->'data') on conflict(id) do update set data=excluded.data,updated_at=now(); end if;
  if r.partner_payload is not null then
   pp=r.partner_payload;
   if pp->>'kind'='existing' then pid2=pp->>'player_id'; else pid2='p_'||gen_random_uuid()::text; insert into public.players(id,data) values(pid2,pp->'data') on conflict(id) do update set data=excluded.data,updated_at=now(); end if;
  end if;
  update public.public_registrations set status='accepted',primary_player_id=pid1,partner_player_id=pid2,updated_at=now() where id=r.id;
 elsif p_action='waitlist' then update public.public_registrations set status='waitlist',updated_at=now() where id=r.id;
 elsif p_action='rejected' then update public.public_registrations set status='rejected',updated_at=now() where id=r.id;
 else raise exception 'Azione non valida'; end if;
 ids=jsonb_build_array(pid1,pid2);
 return jsonb_build_object('status',p_action,'player_ids',ids);
end$$;

-- funzioni campionato e rose
create or replace function public.public_championship_team_for_captain(p_token text) returns jsonb language sql security definer set search_path=public as $$select to_jsonb(t) from public.championship_teams t where t.invite_token=p_token and t.access_enabled=true limit 1$$;
create or replace function public.claim_championship_team_access(p_token text) returns jsonb language plpgsql security definer set search_path=public as $$declare t public.championship_teams; em text;begin if auth.uid() is null then raise exception 'Accedi prima di continuare';end if;select email into em from auth.users where id=auth.uid();select * into t from public.championship_teams where invite_token=p_token and access_enabled=true limit 1;if not found then raise exception 'Accesso non abilitato';end if;if lower(coalesce(em,''))<>lower(coalesce(t.captain_email,'')) then raise exception 'Usa l’email del capitano registrata per questa squadra';end if;insert into public.captain_team_access(user_id,team_id) values(auth.uid(),t.id) on conflict do nothing;return to_jsonb(t);end$$;
create or replace function public.public_championship_team_for_roster(p_token text) returns jsonb language sql security definer set search_path=public as $$select jsonb_build_object('id',t.id,'team_name',t.team_name,'series',t.series,'club_legal_name',t.club_legal_name,'team_logo_url',t.team_logo_url,'roster_open',t.roster_open) from public.championship_teams t where t.player_invite_token=p_token and t.roster_open=true and t.player_self_registration_enabled=true limit 1$$;
create or replace function public.public_submit_championship_roster_player(p_token text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare tid text; rid uuid;begin select id into tid from public.championship_teams where player_invite_token=p_token and roster_open=true and player_self_registration_enabled=true;if tid is null then raise exception 'Raccolta rosa chiusa o link non valido';end if;insert into public.championship_roster_players(team_id,first_name,last_name,birth_date,birth_place,postal_code,residence_town,residence_province,phone,email,gender,level,notes,photo_data,submitted_by) values(tid,p_payload->>'first_name',p_payload->>'last_name',(p_payload->>'birth_date')::date,p_payload->>'birth_place',p_payload->>'postal_code',p_payload->>'residence_town',upper(p_payload->>'residence_province'),p_payload->>'phone',lower(p_payload->>'email'),p_payload->>'gender',p_payload->>'level',p_payload->>'notes',p_payload->>'photo_data',auth.uid()) on conflict(team_id,email) do update set first_name=excluded.first_name,last_name=excluded.last_name,birth_date=excluded.birth_date,birth_place=excluded.birth_place,postal_code=excluded.postal_code,residence_town=excluded.residence_town,residence_province=excluded.residence_province,phone=excluded.phone,gender=excluded.gender,level=excluded.level,notes=excluded.notes,photo_data=excluded.photo_data,status='pending',decision_reason=null,updated_at=now() returning id into rid;return jsonb_build_object('id',rid,'message','Richiesta inviata e in attesa di approvazione.');end$$;
create or replace function public.decide_championship_roster_player(p_player_id uuid,p_decision text,p_reason text default null) returns jsonb language plpgsql security definer set search_path=public as $$declare tid text; allowed boolean;begin if p_decision not in('approved','rejected') then raise exception 'Decisione non valida';end if;select team_id into tid from public.championship_roster_players where id=p_player_id;allowed=exists(select 1 from public.profiles where id=auth.uid() and role='admin') or exists(select 1 from public.captain_team_access where user_id=auth.uid() and team_id=tid);if not allowed then raise exception 'Non autorizzato';end if;update public.championship_roster_players set status=p_decision,decision_reason=p_reason,updated_at=now() where id=p_player_id;return jsonb_build_object('status',p_decision);end$$;

-- RLS e permessi
alter table public.profiles enable row level security;alter table public.players enable row level security;alter table public.tournaments enable row level security;alter table public.public_registrations enable row level security;alter table public.championship_teams enable row level security;alter table public.captain_team_access enable row level security;alter table public.championship_roster_players enable row level security;
do $$declare r record;begin for r in select schemaname,tablename,policyname from pg_policies where schemaname='public' and tablename in('profiles','players','tournaments','public_registrations','championship_teams','captain_team_access','championship_roster_players') loop execute format('drop policy if exists %I on %I.%I',r.policyname,r.schemaname,r.tablename);end loop;end$$;
create policy profiles_own on public.profiles for select to authenticated using(id=auth.uid());
create policy players_auth on public.players for all to authenticated using(true) with check(true);
create policy tournaments_auth on public.tournaments for all to authenticated using(true) with check(true);
create policy registrations_auth on public.public_registrations for all to authenticated using(true) with check(true);
create policy teams_admin_select on public.championship_teams for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin') or exists(select 1 from public.captain_team_access a where a.user_id=auth.uid() and a.team_id=id));
create policy teams_admin_update on public.championship_teams for update to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin') or exists(select 1 from public.captain_team_access a where a.user_id=auth.uid() and a.team_id=id)) with check(true);
create policy access_own on public.captain_team_access for select to authenticated using(user_id=auth.uid());
create policy roster_manage on public.championship_roster_players for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin') or exists(select 1 from public.captain_team_access a where a.user_id=auth.uid() and a.team_id=team_id)) with check(true);
grant usage on schema public to anon,authenticated;grant select,insert,update,delete on public.players,public.tournaments,public.public_registrations,public.championship_teams,public.captain_team_access,public.championship_roster_players to authenticated;grant execute on function public.public_tournament_for_registration(text),public.public_search_players_for_registration(text,text),public.public_submit_tournament_registration_request(text,text,jsonb,jsonb),public.public_championship_team_for_captain(text),public.public_championship_team_for_roster(text),public.public_submit_championship_roster_player(text,jsonb) to anon,authenticated;grant execute on function public.admin_process_public_registration(text,text,integer),public.claim_championship_team_access(text),public.decide_championship_roster_player(uuid,text,text) to authenticated;

-- storage loghi/foto
insert into storage.buckets(id,name,public) values('padel-arena-images','padel-arena-images',true) on conflict(id) do update set public=true;
drop policy if exists images_public_read on storage.objects;create policy images_public_read on storage.objects for select to public using(bucket_id='padel-arena-images');drop policy if exists images_auth_write on storage.objects;create policy images_auth_write on storage.objects for all to authenticated using(bucket_id='padel-arena-images') with check(bucket_id='padel-arena-images');
notify pgrst,'reload schema';
